{
  "name": "ttsr-rules",
  "version": "0.1.0",
  "description": "oh-my-pi TTSR rules: a regex rule denies the tool call that would break it, with the rule as the reason; a question rule is judged after each turn.",
  "dependencies": [
    "decision-model"
  ],
  "userConfig": {
    "questionRules": {
      "type": "boolean",
      "title": "Question rules",
      "description": "Judge rules with a `question:` after each main-thread turn",
      "default": true
    },
    "questionAction": {
      "type": "string",
      "title": "When a question rule fires",
      "description": "note: add the rule for the next turn; resume: also start a turn to fix it",
      "options": [
        "note",
        "resume"
      ],
      "default": "note"
    }
  }
}
